CREATE TABLE IF NOT EXISTS schema_migrations (version VARCHAR(120) PRIMARY KEY, applied_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE roles (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(40) NOT NULL UNIQUE);
CREATE TABLE permissions (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(80) NOT NULL UNIQUE);
CREATE TABLE role_permissions (role_id INT UNSIGNED NOT NULL, permission_id INT UNSIGNED NOT NULL, PRIMARY KEY(role_id,permission_id), FOREIGN KEY(role_id) REFERENCES roles(id), FOREIGN KEY(permission_id) REFERENCES permissions(id));
CREATE TABLE users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role_id INT UNSIGNED NOT NULL, status ENUM('active','suspended') NOT NULL DEFAULT 'active', email_verified_at DATETIME NULL, terms_accepted_at DATETIME NOT NULL, onboarding_completed_at DATETIME NULL, timezone VARCHAR(80) NOT NULL DEFAULT 'Africa/Lagos', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(role_id) REFERENCES roles(id), INDEX idx_users_created(created_at));
CREATE TABLE auth_sessions (id CHAR(64) PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, expires_at DATETIME NOT NULL, revoked_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX idx_auth_user(user_id));
CREATE TABLE refresh_tokens (token_hash CHAR(64) PRIMARY KEY, session_id CHAR(64) NOT NULL, expires_at DATETIME NOT NULL, used_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(session_id) REFERENCES auth_sessions(id) ON DELETE CASCADE);
CREATE TABLE account_tokens (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, purpose ENUM('verify','reset') NOT NULL, expires_at DATETIME NOT NULL, used_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE rate_limits (bucket CHAR(64) PRIMARY KEY, attempts INT UNSIGNED NOT NULL DEFAULT 1, resets_at BIGINT UNSIGNED NOT NULL);
CREATE TABLE user_preferences (user_id BIGINT UNSIGNED PRIMARY KEY, goal VARCHAR(60) NOT NULL DEFAULT 'new_skill', experience VARCHAR(30) NOT NULL DEFAULT 'beginner', daily_minutes SMALLINT UNSIGNED NOT NULL DEFAULT 15, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, CHECK(daily_minutes BETWEEN 5 AND 180));
CREATE TABLE onboarding_responses (user_id BIGINT UNSIGNED PRIMARY KEY, step TINYINT UNSIGNED NOT NULL DEFAULT 0, responses JSON NOT NULL, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(100) NOT NULL UNIQUE, slug VARCHAR(120) NOT NULL UNIQUE, description TEXT NOT NULL, icon VARCHAR(30) NOT NULL DEFAULT 'code', color VARCHAR(20) NOT NULL DEFAULT 'orange', active BOOLEAN NOT NULL DEFAULT 1);
CREATE TABLE user_interests (user_id BIGINT UNSIGNED NOT NULL, category_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(user_id,category_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE CASCADE);
CREATE TABLE learning_paths (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category_id BIGINT UNSIGNED NOT NULL, title VARCHAR(160) NOT NULL, slug VARCHAR(190) NOT NULL UNIQUE, description TEXT NOT NULL, objectives TEXT NOT NULL, difficulty ENUM('beginner','intermediate','advanced') NOT NULL DEFAULT 'beginner', status ENUM('draft','published','archived') NOT NULL DEFAULT 'draft', certificate_enabled BOOLEAN NOT NULL DEFAULT 1, certificate_min_score SMALLINT UNSIGNED NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(category_id) REFERENCES categories(id), INDEX idx_paths_status(status));
CREATE TABLE stages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, path_id BIGINT UNSIGNED NOT NULL, title VARCHAR(160) NOT NULL, description TEXT NOT NULL, position SMALLINT UNSIGNED NOT NULL DEFAULT 0, FOREIGN KEY(path_id) REFERENCES learning_paths(id) ON DELETE CASCADE, INDEX idx_stage_order(path_id,position));
CREATE TABLE stage_prerequisites (stage_id BIGINT UNSIGNED NOT NULL, required_stage_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(stage_id,required_stage_id), FOREIGN KEY(stage_id) REFERENCES stages(id) ON DELETE CASCADE, FOREIGN KEY(required_stage_id) REFERENCES stages(id) ON DELETE CASCADE, CHECK(stage_id <> required_stage_id));
CREATE TABLE stage_overrides (user_id BIGINT UNSIGNED NOT NULL, stage_id BIGINT UNSIGNED NOT NULL, granted_by BIGINT UNSIGNED NOT NULL, reason VARCHAR(500) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,stage_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(stage_id) REFERENCES stages(id) ON DELETE CASCADE, FOREIGN KEY(granted_by) REFERENCES users(id));
CREATE TABLE modules (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, stage_id BIGINT UNSIGNED NOT NULL, title VARCHAR(160) NOT NULL, position SMALLINT UNSIGNED NOT NULL DEFAULT 0, FOREIGN KEY(stage_id) REFERENCES stages(id) ON DELETE CASCADE);
CREATE TABLE lessons (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, module_id BIGINT UNSIGNED NOT NULL, title VARCHAR(160) NOT NULL, description TEXT NOT NULL, objectives TEXT NOT NULL, content MEDIUMTEXT NOT NULL, takeaways TEXT NOT NULL, youtube_id VARCHAR(11) NULL, duration_minutes SMALLINT UNSIGNED NOT NULL DEFAULT 10, require_checklist BOOLEAN NOT NULL DEFAULT 0, required BOOLEAN NOT NULL DEFAULT 1, position SMALLINT UNSIGNED NOT NULL DEFAULT 0, status ENUM('draft','published','archived') NOT NULL DEFAULT 'draft', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(module_id) REFERENCES modules(id) ON DELETE CASCADE, INDEX idx_lessons_status(status));
CREATE TABLE lesson_prerequisites (lesson_id BIGINT UNSIGNED NOT NULL, required_lesson_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(lesson_id,required_lesson_id), FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE CASCADE, FOREIGN KEY(required_lesson_id) REFERENCES lessons(id) ON DELETE CASCADE, CHECK(lesson_id <> required_lesson_id));
CREATE TABLE lesson_resources (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, lesson_id BIGINT UNSIGNED NOT NULL, title VARCHAR(160) NOT NULL, url VARCHAR(2000) NOT NULL, FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE CASCADE);
CREATE TABLE lesson_checklists (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, lesson_id BIGINT UNSIGNED NOT NULL, label VARCHAR(500) NOT NULL, position SMALLINT UNSIGNED NOT NULL DEFAULT 0, FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE CASCADE);
CREATE TABLE checklist_progress (user_id BIGINT UNSIGNED NOT NULL, checklist_id BIGINT UNSIGNED NOT NULL, completed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,checklist_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(checklist_id) REFERENCES lesson_checklists(id) ON DELETE CASCADE);
CREATE TABLE learner_notes (user_id BIGINT UNSIGNED NOT NULL, lesson_id BIGINT UNSIGNED NOT NULL, content TEXT NOT NULL, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY(user_id,lesson_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE CASCADE);
CREATE TABLE enrolments (user_id BIGINT UNSIGNED NOT NULL, path_id BIGINT UNSIGNED NOT NULL, enrolled_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, completed_at DATETIME NULL, PRIMARY KEY(user_id,path_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(path_id) REFERENCES learning_paths(id) ON DELETE CASCADE);
CREATE TABLE lesson_progress (user_id BIGINT UNSIGNED NOT NULL, lesson_id BIGINT UNSIGNED NOT NULL, completed_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,lesson_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE CASCADE);
CREATE TABLE quizzes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, stage_id BIGINT UNSIGNED NOT NULL, lesson_id BIGINT UNSIGNED NULL, title VARCHAR(160) NOT NULL, instructions TEXT NOT NULL, passing_score SMALLINT UNSIGNED NOT NULL DEFAULT 70, attempt_limit SMALLINT UNSIGNED NOT NULL DEFAULT 0, time_limit_minutes SMALLINT UNSIGNED NOT NULL DEFAULT 0, show_answers BOOLEAN NOT NULL DEFAULT 1, required BOOLEAN NOT NULL DEFAULT 1, uses_lives BOOLEAN NOT NULL DEFAULT 0, status ENUM('draft','published','archived') NOT NULL DEFAULT 'draft', FOREIGN KEY(stage_id) REFERENCES stages(id) ON DELETE CASCADE, FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE SET NULL, CHECK(passing_score <= 100));
CREATE TABLE quiz_questions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, quiz_id BIGINT UNSIGNED NOT NULL, type ENUM('single','multiple','boolean','short') NOT NULL, prompt TEXT NOT NULL, explanation TEXT NOT NULL, points SMALLINT UNSIGNED NOT NULL DEFAULT 1, position SMALLINT UNSIGNED NOT NULL DEFAULT 0, FOREIGN KEY(quiz_id) REFERENCES quizzes(id) ON DELETE CASCADE, CHECK(points > 0));
CREATE TABLE answer_options (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, question_id BIGINT UNSIGNED NOT NULL, label TEXT NOT NULL, is_correct BOOLEAN NOT NULL DEFAULT 0, position SMALLINT UNSIGNED NOT NULL DEFAULT 0, FOREIGN KEY(question_id) REFERENCES quiz_questions(id) ON DELETE CASCADE);
CREATE TABLE quiz_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, quiz_id BIGINT UNSIGNED NOT NULL, status ENUM('in_progress','pending_review','passed','failed') NOT NULL DEFAULT 'in_progress', score DECIMAL(6,2) NULL, awarded_points DECIMAL(8,2) NOT NULL DEFAULT 0, total_points DECIMAL(8,2) NOT NULL DEFAULT 0, started_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, deadline_at DATETIME NULL, submitted_at DATETIME NULL, graded_by BIGINT UNSIGNED NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(quiz_id) REFERENCES quizzes(id), FOREIGN KEY(graded_by) REFERENCES users(id), INDEX idx_attempts(user_id,quiz_id,status));
CREATE TABLE quiz_responses (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, attempt_id BIGINT UNSIGNED NOT NULL, question_id BIGINT UNSIGNED NOT NULL, answer_text TEXT NULL, awarded_points DECIMAL(8,2) NULL, feedback TEXT NULL, UNIQUE(attempt_id,question_id), FOREIGN KEY(attempt_id) REFERENCES quiz_attempts(id) ON DELETE CASCADE, FOREIGN KEY(question_id) REFERENCES quiz_questions(id));
CREATE TABLE quiz_response_options (response_id BIGINT UNSIGNED NOT NULL, option_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(response_id,option_id), FOREIGN KEY(response_id) REFERENCES quiz_responses(id) ON DELETE CASCADE, FOREIGN KEY(option_id) REFERENCES answer_options(id));
CREATE TABLE assignments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, stage_id BIGINT UNSIGNED NOT NULL, lesson_id BIGINT UNSIGNED NULL, title VARCHAR(160) NOT NULL, description TEXT NOT NULL, instructions TEXT NOT NULL, objectives TEXT NOT NULL, due_at DATETIME NULL, max_score SMALLINT UNSIGNED NOT NULL DEFAULT 100, passing_score SMALLINT UNSIGNED NOT NULL DEFAULT 60, allow_text BOOLEAN NOT NULL DEFAULT 1, allow_url BOOLEAN NOT NULL DEFAULT 1, allow_file BOOLEAN NOT NULL DEFAULT 0, required BOOLEAN NOT NULL DEFAULT 1, status ENUM('draft','published','archived') NOT NULL DEFAULT 'draft', FOREIGN KEY(stage_id) REFERENCES stages(id) ON DELETE CASCADE, FOREIGN KEY(lesson_id) REFERENCES lessons(id) ON DELETE SET NULL);
CREATE TABLE grading_rubrics (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, assignment_id BIGINT UNSIGNED NOT NULL, criterion VARCHAR(300) NOT NULL, max_points SMALLINT UNSIGNED NOT NULL, FOREIGN KEY(assignment_id) REFERENCES assignments(id) ON DELETE CASCADE);
CREATE TABLE assignment_submissions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, assignment_id BIGINT UNSIGNED NOT NULL, content TEXT NOT NULL, project_url VARCHAR(2000) NULL, file_key VARCHAR(100) NULL, file_name VARCHAR(200) NULL, file_mime VARCHAR(80) NULL, status ENUM('draft','submitted','under_review','revision_requested','resubmitted','graded','accepted') NOT NULL DEFAULT 'draft', score DECIMAL(8,2) NULL, reviewer_id BIGINT UNSIGNED NULL, submitted_at DATETIME NULL, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE(user_id,assignment_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(assignment_id) REFERENCES assignments(id), FOREIGN KEY(reviewer_id) REFERENCES users(id), INDEX idx_submissions_status(status));
CREATE TABLE assignment_feedback (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, submission_id BIGINT UNSIGNED NOT NULL, author_id BIGINT UNSIGNED NOT NULL, action VARCHAR(40) NOT NULL, feedback TEXT NOT NULL, score DECIMAL(8,2) NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(submission_id) REFERENCES assignment_submissions(id) ON DELETE CASCADE, FOREIGN KEY(author_id) REFERENCES users(id));
CREATE TABLE submission_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, submission_id BIGINT UNSIGNED NOT NULL, content TEXT NOT NULL, project_url VARCHAR(2000) NULL, file_key VARCHAR(100) NULL, status VARCHAR(40) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(submission_id) REFERENCES assignment_submissions(id) ON DELETE CASCADE);
CREATE TABLE study_schedules (user_id BIGINT UNSIGNED PRIMARY KEY, reminder_time TIME NOT NULL DEFAULT '18:00:00', reminders_enabled BOOLEAN NOT NULL DEFAULT 0, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE study_days (user_id BIGINT UNSIGNED NOT NULL, weekday TINYINT UNSIGNED NOT NULL, PRIMARY KEY(user_id,weekday), FOREIGN KEY(user_id) REFERENCES study_schedules(user_id) ON DELETE CASCADE, CHECK(weekday BETWEEN 1 AND 7));
CREATE TABLE activity_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, kind VARCHAR(40) NOT NULL, reference_id BIGINT UNSIGNED NOT NULL, local_date DATE NOT NULL, goal_minutes SMALLINT UNSIGNED NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,kind,reference_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX idx_activity_date(user_id,local_date));
CREATE TABLE daily_activity (user_id BIGINT UNSIGNED NOT NULL, local_date DATE NOT NULL, goal_minutes INT UNSIGNED NOT NULL DEFAULT 0, goal_target SMALLINT UNSIGNED NOT NULL, qualified_at DATETIME NULL, protected BOOLEAN NOT NULL DEFAULT 0, PRIMARY KEY(user_id,local_date), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE streak_records (user_id BIGINT UNSIGNED PRIMARY KEY, current_streak INT UNSIGNED NOT NULL DEFAULT 0, best_streak INT UNSIGNED NOT NULL DEFAULT 0, last_date DATE NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE reward_rules (kind VARCHAR(40) PRIMARY KEY, xp SMALLINT UNSIGNED NOT NULL DEFAULT 0, enabled BOOLEAN NOT NULL DEFAULT 1);
CREATE TABLE xp_transactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, amount INT NOT NULL, reason VARCHAR(200) NOT NULL, idempotency_key VARCHAR(190) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,idempotency_key), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX idx_xp_date(user_id,created_at));
CREATE TABLE coin_transactions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, amount INT NOT NULL, reason VARCHAR(200) NOT NULL, idempotency_key VARCHAR(190) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,idempotency_key), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE level_definitions (level SMALLINT UNSIGNED PRIMARY KEY, title VARCHAR(80) NOT NULL, minimum_xp INT UNSIGNED NOT NULL UNIQUE);
CREATE TABLE achievements (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(120) NOT NULL, description VARCHAR(500) NOT NULL, metric ENUM('streak','lessons','xp') NOT NULL, threshold_value INT UNSIGNED NOT NULL, xp_reward SMALLINT UNSIGNED NOT NULL DEFAULT 0, protection_reward TINYINT UNSIGNED NOT NULL DEFAULT 0, icon VARCHAR(30) NOT NULL DEFAULT 'award', active BOOLEAN NOT NULL DEFAULT 1);
CREATE TABLE learner_achievements (user_id BIGINT UNSIGNED NOT NULL, achievement_id BIGINT UNSIGNED NOT NULL, awarded_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(user_id,achievement_id), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(achievement_id) REFERENCES achievements(id));
CREATE TABLE streak_protections (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, source_key VARCHAR(190) NOT NULL, used_date DATE NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,source_key), UNIQUE(user_id,used_date), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE lives_records (user_id BIGINT UNSIGNED PRIMARY KEY, remaining TINYINT UNSIGNED NOT NULL, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE skill_nodes (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, path_id BIGINT UNSIGNED NOT NULL, stage_id BIGINT UNSIGNED NOT NULL UNIQUE, label VARCHAR(120) NOT NULL, FOREIGN KEY(path_id) REFERENCES learning_paths(id) ON DELETE CASCADE, FOREIGN KEY(stage_id) REFERENCES stages(id) ON DELETE CASCADE);
CREATE TABLE skill_connections (node_id BIGINT UNSIGNED NOT NULL, prerequisite_node_id BIGINT UNSIGNED NOT NULL, PRIMARY KEY(node_id,prerequisite_node_id), FOREIGN KEY(node_id) REFERENCES skill_nodes(id) ON DELETE CASCADE, FOREIGN KEY(prerequisite_node_id) REFERENCES skill_nodes(id) ON DELETE CASCADE, CHECK(node_id <> prerequisite_node_id));
CREATE TABLE portfolio_projects (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, path_id BIGINT UNSIGNED NULL, title VARCHAR(160) NOT NULL, slug VARCHAR(190) NOT NULL UNIQUE, description TEXT NOT NULL, project_url VARCHAR(2000) NULL, repository_url VARCHAR(2000) NULL, visibility ENUM('private','public') NOT NULL DEFAULT 'private', completed_on DATE NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(path_id) REFERENCES learning_paths(id) ON DELETE SET NULL, INDEX idx_projects_visibility(visibility,created_at));
CREATE TABLE project_skills (project_id BIGINT UNSIGNED NOT NULL, skill VARCHAR(80) NOT NULL, PRIMARY KEY(project_id,skill), FOREIGN KEY(project_id) REFERENCES portfolio_projects(id) ON DELETE CASCADE);
CREATE TABLE project_images (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, project_id BIGINT UNSIGNED NOT NULL, file_key VARCHAR(100) NOT NULL, file_name VARCHAR(200) NOT NULL, file_mime VARCHAR(80) NOT NULL, FOREIGN KEY(project_id) REFERENCES portfolio_projects(id) ON DELETE CASCADE);
CREATE TABLE buddy_relationships (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, requester_id BIGINT UNSIGNED NOT NULL, recipient_id BIGINT UNSIGNED NOT NULL, status ENUM('pending','accepted','declined','blocked') NOT NULL DEFAULT 'pending', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(requester_id,recipient_id), FOREIGN KEY(requester_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(recipient_id) REFERENCES users(id) ON DELETE CASCADE, CHECK(requester_id <> recipient_id));
CREATE TABLE friend_challenges (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, creator_id BIGINT UNSIGNED NOT NULL, friend_id BIGINT UNSIGNED NOT NULL, title VARCHAR(160) NOT NULL, target SMALLINT UNSIGNED NOT NULL, deadline DATE NOT NULL, status ENUM('pending','accepted','declined') NOT NULL DEFAULT 'pending', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(creator_id) REFERENCES users(id), FOREIGN KEY(friend_id) REFERENCES users(id), CHECK(creator_id <> friend_id));
CREATE TABLE peer_review_assignments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, project_id BIGINT UNSIGNED NOT NULL, reviewer_id BIGINT UNSIGNED NOT NULL, due_at DATETIME NOT NULL, status ENUM('assigned','submitted','hidden') NOT NULL DEFAULT 'assigned', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(project_id,reviewer_id), FOREIGN KEY(project_id) REFERENCES portfolio_projects(id) ON DELETE CASCADE, FOREIGN KEY(reviewer_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE peer_review_questions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, prompt VARCHAR(300) NOT NULL, max_score TINYINT UNSIGNED NOT NULL DEFAULT 5, active BOOLEAN NOT NULL DEFAULT 1);
CREATE TABLE peer_review_responses (review_id BIGINT UNSIGNED NOT NULL, question_id BIGINT UNSIGNED NOT NULL, score TINYINT UNSIGNED NOT NULL, feedback TEXT NOT NULL, PRIMARY KEY(review_id,question_id), FOREIGN KEY(review_id) REFERENCES peer_review_assignments(id) ON DELETE CASCADE, FOREIGN KEY(question_id) REFERENCES peer_review_questions(id));
CREATE TABLE community_reports (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, reporter_id BIGINT UNSIGNED NOT NULL, reported_user_id BIGINT UNSIGNED NOT NULL, reason TEXT NOT NULL, status ENUM('open','resolved') NOT NULL DEFAULT 'open', resolution TEXT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(reporter_id) REFERENCES users(id), FOREIGN KEY(reported_user_id) REFERENCES users(id));
CREATE TABLE certificates (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, identifier CHAR(32) NOT NULL UNIQUE, user_id BIGINT UNSIGNED NOT NULL, path_id BIGINT UNSIGNED NOT NULL, learner_name VARCHAR(120) NOT NULL, path_title VARCHAR(160) NOT NULL, issued_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, revoked_at DATETIME NULL, revocation_reason VARCHAR(500) NULL, UNIQUE(user_id,path_id), FOREIGN KEY(user_id) REFERENCES users(id), FOREIGN KEY(path_id) REFERENCES learning_paths(id));
CREATE TABLE certificate_verifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, certificate_id BIGINT UNSIGNED NOT NULL, checked_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(certificate_id) REFERENCES certificates(id) ON DELETE CASCADE);
CREATE TABLE referral_codes (user_id BIGINT UNSIGNED PRIMARY KEY, code VARCHAR(20) NOT NULL UNIQUE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE referrals (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, referrer_id BIGINT UNSIGNED NOT NULL, referred_id BIGINT UNSIGNED NOT NULL UNIQUE, status ENUM('pending','qualified','rewarded','rejected') NOT NULL DEFAULT 'pending', qualified_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(referrer_id) REFERENCES users(id), FOREIGN KEY(referred_id) REFERENCES users(id), CHECK(referrer_id <> referred_id));
CREATE TABLE referral_campaigns (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, title VARCHAR(160) NOT NULL, enabled BOOLEAN NOT NULL DEFAULT 0, reward_type ENUM('xp','coins') NOT NULL DEFAULT 'xp', referrer_reward SMALLINT UNSIGNED NOT NULL DEFAULT 50, referred_reward SMALLINT UNSIGNED NOT NULL DEFAULT 0, qualifying_lessons SMALLINT UNSIGNED NOT NULL DEFAULT 3, require_verified BOOLEAN NOT NULL DEFAULT 1, max_rewards SMALLINT UNSIGNED NOT NULL DEFAULT 20, starts_at DATETIME NULL, ends_at DATETIME NULL);
CREATE TABLE referral_rewards (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, referral_id BIGINT UNSIGNED NOT NULL UNIQUE, campaign_id BIGINT UNSIGNED NOT NULL, amount INT UNSIGNED NOT NULL, reward_type ENUM('xp','coins') NOT NULL, awarded_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(referral_id) REFERENCES referrals(id), FOREIGN KEY(campaign_id) REFERENCES referral_campaigns(id));
CREATE TABLE notification_preferences (user_id BIGINT UNSIGNED PRIMARY KEY, study BOOLEAN NOT NULL DEFAULT 1, streak BOOLEAN NOT NULL DEFAULT 1, deadlines BOOLEAN NOT NULL DEFAULT 1, feedback BOOLEAN NOT NULL DEFAULT 1, milestones BOOLEAN NOT NULL DEFAULT 1, weekly BOOLEAN NOT NULL DEFAULT 1, email BOOLEAN NOT NULL DEFAULT 0, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, kind VARCHAR(40) NOT NULL, title VARCHAR(160) NOT NULL, body TEXT NOT NULL, link VARCHAR(500) NOT NULL DEFAULT '/dashboard', dedup_key VARCHAR(190) NOT NULL, read_at DATETIME NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,dedup_key), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX idx_notifications(user_id,read_at,created_at));
CREATE TABLE mail_outbox (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, subject VARCHAR(200) NOT NULL, body TEXT NOT NULL, dedup_key VARCHAR(190) NOT NULL UNIQUE, status ENUM('queued','sending','sent','failed') NOT NULL DEFAULT 'queued', attempts TINYINT UNSIGNED NOT NULL DEFAULT 0, last_error VARCHAR(500) NULL, queued_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, sent_at DATETIME NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE weekly_reports (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id BIGINT UNSIGNED NOT NULL, week_start DATE NOT NULL, week_end DATE NOT NULL, lessons_completed INT UNSIGNED NOT NULL, quizzes_attempted INT UNSIGNED NOT NULL, average_quiz_score DECIMAL(6,2) NULL, assignments_submitted INT UNSIGNED NOT NULL, xp_earned INT NOT NULL, goals_met INT UNSIGNED NOT NULL, streak_days INT UNSIGNED NOT NULL, suggested_next TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(user_id,week_start), FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE system_settings (setting_key VARCHAR(100) PRIMARY KEY, setting_value TEXT NOT NULL, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, actor_id BIGINT UNSIGNED NULL, action VARCHAR(100) NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id VARCHAR(100) NULL, details TEXT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(actor_id) REFERENCES users(id) ON DELETE SET NULL, INDEX idx_audit_created(created_at), INDEX idx_audit_actor(actor_id));
